WITH recent_inventory AS (SELECT *, DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_label FROM inventory WHERE quantity BETWEEN 75 AND 176 OR quantity > 220), inventory_stats AS (SELECT DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_month, MAX(quantity) AS max_quantity, COUNT(*) AS total_count FROM recent_inventory GROUP BY DATE_FORMAT(last_restock, 'yyyy-MM')) SELECT * FROM inventory_stats WHERE total_count < 8 ORDER BY last_restock_month
